from .pricing import quote


class RouteEngine:
    def __init__(self):
        self.history = []

    def rank(self, parcels):
        # Higher priority is sorted first, and duplicate parcel_ids keep the
        # first occurrence. A set makes deduplication O(n) instead of O(n^2).
        unique = []
        seen = set()
        for p in parcels:
            if p.parcel_id not in seen:
                seen.add(p.parcel_id)
                unique.append(p)
        return sorted(unique, key=lambda p: (-p.priority, quote(p.zone, p.weight_kg)))

    def total(self, parcels):
        total = 0
        for p in parcels:
            total += quote(p.zone, p.weight_kg)
        self.history.append(total)
        return round(total, 2)
